function mapDarkStyle(style: any) {
  if (!style || typeof style !== 'object') return style;
  const bg: Record<string, string> = { '#F7F8FC': '#11111A', white: '#1D1D2A', '#FCFCFE': '#242433', '#F6F5FC': '#29283B', '#F7F6FD': '#29283B', '#F8F7FF': '#29283B', '#F3F2F8': '#302F41', '#F1F1F5': '#333342', '#F0EFF5': '#343344', '#F0EEFF': '#302C50', '#FFF9E9': '#3A3428', '#FFF5E8': '#3B3025', '#FFF5DA': '#3B3425', '#FFF8F6': '#3A2B2B', '#FFF5F4': '#3A292B' };
  const fg: Record<string, string> = { '#17182B': '#F4F2FC', '#55576B': '#D3D1E0', '#505267': '#D3D1E0', '#65677A': '#D3D1E0', '#77798E': '#B8B6C9', '#888BA0': '#AAA8BB', '#9697A6': '#AAA8BB', '#A5A6B5': '#9290A4', '#5143C6': '#C0B9FF', '#238268': '#71D7B6' };
  const border: Record<string, string> = { '#EEEEF4': '#373747', '#ECEBF2': '#373747', '#ECECF3': '#373747', '#E7E7EF': '#414052', '#E6E5EF': '#414052', '#F0EFF5': '#373747', '#F2F1F6': '#373747', '#EAE8F3': '#373747', '#E5E2F4': '#4A4667', '#E8E6F5': '#373747' };
  return Object.fromEntries(Object.entries(style).map(([key, value]) => [key, typeof value === 'string' ? (key === 'backgroundColor' ? bg[value] || value : key === 'color' ? fg[value] || value : key.toLowerCase().includes('bordercolor') ? border[value] || value : value) : value]));
}
const darkStyles = Object.fromEntries(Object.entries(lightStyles).map(([key, value]) => [key, mapDarkStyle(value)])) as typeof lightStyles;
let st = lightStyles;
export function setScreenDarkMode(enabled: boolean) { st = enabled ? darkStyles : lightStyles; }
